func (q *Queries) UpsertSavedRepo(ctx context.Context, arg UpsertSavedRepoParams) error {
	_, err := q.db.Exec(ctx, upsertSavedRepo, arg.UserId, arg.RepositoryId, arg.PaidCredits)
	return err
}
